import java.util.*;
import java.io.*;

public class Main {
    static final int N = 10;
    static final int M = 1000007;
    static final int K = 200;
    static final int p = 1000000007;
    static class BitSet40 {
        long[] bits = new long[1]; // only 40 bits needed
        public BitSet40() {
            bits[0] = 0L;
        }
        public void set(int index) {
            bits[0] |= (1L << index);
        }
        public boolean get(int index) {
            return ((bits[0] >> index) & 1L) == 1L;
        }
        public void or(BitSet40 other) {
            this.bits[0] |= other.bits[0];
        }
        public boolean equals(BitSet40 other) {
            return this.bits[0] == other.bits[0];
        }
        public BitSet40 clone() {
            BitSet40 clone = new BitSet40();
            clone.bits[0] = this.bits[0];
            return clone;
        }
    }

    static int n;
    static int[] e = new int[N];
    static int[] s = new int[M];
    static int[] wf = new int[K];
    static int[][] q = new int[N][K];
    static int[][] f = new int[N + 1][N + 1];
    static int[][] ans = new int[N + 1][M];
    static BitSet40[] wq = new BitSet40[N + 1][M];
    static Map<BitSet40, Integer>[] rt = new HashMap[N + 1];

    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    static int readInt() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return Integer.parseInt(st.nextToken());
    }

    static long modPow(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % p;
            base = (base * base) % p;
            exp >>= 1;
        }
        return result;
    }

    static void processNode(int u) {
        q[u][0] = 0;
        int total_os = 0, total_of = 0;
        for (int i = 0; i < (1 << n); i++) {
            if (s[i] == u) {
                q[u][++q[u][0]] = i;
                wf[i] = ++total_os;
            }
        }
        for (int i = 1; i <= e[u - 1]; i++) {
            if (ans[u - 1][i] == 0) continue;
            for (int h = 1; h < (1 << n); h++) {
                long prob = 1;
                for (int c = 0; c < n; c++) {
                    if (((1 << c) & h) != 0) {
                        prob = (prob * f[u][c + 1]) % p;
                    } else {
                        prob = (prob * ((1 - f[u][c + 1] + p) % p)) % p;
                    }
                }
                BitSet40 c = wq[u - 1][i];
                BitSet40 hc = new BitSet40();
                boolean changed = false;
                for (int x = 1; x <= q[u - 1][0]; x++) {
                    if (c.get(x - 1)) {
                        for (int t = 0; t < n; t++) {
                            if ((((1 << t) & h) != 0) && ((q[u - 1][x] & (1 << t)) == 0)) {
                                int pos = wf[q[u - 1][x] | (1 << t)];
                                hc.set(pos - 1);
                                changed = true;
                            }
                        }
                    }
                }
                if (!changed) continue;
                if (rt[u] == null) {
                    rt[u] = new HashMap<>();
                }
                Integer pos = rt[u].get(hc);
                if (pos == null) {
                    rt[u].put(hc, ++total_of);
                    e[u]++;
                    wq[u][e[u]] = hc;
                    pos = total_of;
                }
                ans[u][pos] = (int) ((ans[u][pos] + prob * ans[u - 1][i]) % p);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        n = readInt();
        for (int i = 0; i <= (1 << n); i++) {
            s[i] = Integer.bitCount(i);
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                f[i][j] = (int) (readInt() * modPow(100, p - 2) % p);
            }
        }
        q[0][0] = 1;
        e[0] = 1;
        ans[0][1] = 1;
        wq[0][1] = new BitSet40();
        wq[0][1].set(0);
        for (int i = 1; i <= n; i++) {
            processNode(i);
        }
        System.out.println(ans[n][1]);
    }
}
